reg clamp1;
always @(posedge clk) begin
    if (rst) begin
        clamp0 <= 1'b0;
        clamp1 <= 1'b0;
    end
    else begin
        clamp0 <= clamp0 | (^acc0In[WIDTH+K0_SHIFT-:2]);
        clamp1 <= clamp1 | (^acc1In[WIDTH+K1_SHIFT-:2]);
    end
end
*/

endmodule
```

