2. Khai báo danh sách cổng đầy đủ, các thanh ghi tuần tự được cập nhật tại sườn xung clock và hỗ trợ reset an toàn.
3. Tuân thủ tuyệt đối quy tắc thiết kế synthesizable: gán đầy đủ giá trị ở mọi nhánh rẽ để triệt tiêu chốt ẩn (no inferred latches) và nối trọn vẹn toàn bộ các chân (no dangling pins).

```verilog
module uart_tx_8bit (
    input  wire       clk,
    input  wire       rst,
    input  wire       tx_start,
    input  wire [7:0] tx_data,
    output reg        tx_serial,
    output reg        tx_busy
);
    localparam IDLE  = 2'b00,
               START = 2'b01,
               DATA  = 2'b10,
               STOP  = 2'b11;

    reg [1:0] state;
    reg [2:0] bit_idx;
    reg [7:0] tx_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state     <= IDLE;
            tx_serial <= 1'b1;
            tx_busy   <= 1'b0;
            bit_idx   <= 3'd0;
            tx_reg    <= 8'd0;
        end else begin
            case (state)
                IDLE: begin
                    tx_serial <= 1'b1;
                    if (tx_start) begin
                        state     <= START;
                        tx_busy   <= 1'b1;
                        tx_reg    <= tx_data;
                        bit_idx   <= 3'd0;
                    end else begin
                        tx_busy   <= 1'b0;
                    end
                end
                START: begin
                    tx_serial <= 1'b0;
                    state     <= DATA;
                end
                DATA: begin
                    tx_serial <= tx_reg[bit_idx];
                    if (bit_idx == 3'd7) begin
                        state <= STOP;
                    end else begin
                        bit_idx <= bit_idx + 1'b1;
                    end
                end
                STOP: begin
                    tx_serial <= 1'b1;
                    state     <= IDLE;
                    tx_busy   <= 1'b0;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule
```

