```verilog
module button_debouncer (
    input  wire clk,
    input  wire rst,
    input  wire btn_in,
    output reg  btn_clean,
    output reg  btn_pressed_pulse
);
    reg [15:0] counter;
    reg        sync_0, sync_1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sync_0            <= 1'b0;
            sync_1            <= 1'b0;
            counter           <= 16'd0;
            btn_clean         <= 1'b0;
            btn_pressed_pulse <= 1'b0;
        end else begin
            sync_0            <= btn_in;
            sync_1            <= sync_0;
            btn_pressed_pulse <= 1'b0;

            if (sync_1 != btn_clean) begin
                counter <= counter + 1'b1;
                if (counter == 16'hFFFF) begin
                    btn_clean <= sync_1;
                    if (sync_1 == 1'b1) begin
                        btn_pressed_pulse <= 1'b1;
                    end
                end
            end else begin
                counter <= 16'd0;
            end
        end
    end
endmodule
