    input  wire [3:0] a,
    input  wire [3:0] b,
    input  wire [2:0]           opcode,
    output reg  [3:0] result,
    output reg                  carry_out,
    output wire                 zero_flag
);
    reg [4:0] temp;
    always @(*) begin
        carry_out = 1'b0;
        temp = 5'd0;
        case (opcode)
            3'b000: begin temp = a + b; result = temp[3:0]; carry_out = temp[4]; end
            3'b001: begin temp = a - b; result = temp[3:0]; carry_out = temp[4]; end
            3'b010: result = a & b;
            3'b011: result = a | b;
            3'b100: result = a ^ b;
            3'b101: result = ~a;
            3'b110: result = a << 1;
            3'b111: result = a >> 1;
            default: result = 4'd0;
        endcase
    end
    assign zero_flag = (result == 4'd0);
endmodule
