    input  wire       clk,
    input  wire       rst,
    input  wire       start,
    input  wire [7:0] tx_data,
    output reg  [7:0] rx_data,
    output reg        sclk,
    output reg        cs_n,
    output reg        mosi,
    input  wire       miso,
    output reg        busy
);
    localparam IDLE = 2'b00, SCLK_LOW = 2'b01, SCLK_HIGH = 2'b10, DONE = 2'b11;
    reg [1:0] state;
    reg [2:0] bit_cnt;
