    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state    <= IDLE;
            sclk     <= 1'b0;
            cs_n     <= 1'b1;
            mosi     <= 1'b0;
            busy     <= 1'b0;
            rx_data  <= 8'd0;
            bit_cnt  <= 3'd7;
            shift_tx <= 8'd0;
            shift_rx <= 8'd0;
