                    cs_n <= 1'b1;
                    busy <= 1'b0;
                    if (start) begin
                        state    <= SCLK_LOW;
                        cs_n     <= 1'b0;
                        busy     <= 1'b1;
                        shift_tx <= tx_data;
                        bit_cnt  <= 3'd7;
