module uart_rx_8bit_clean (
    input  wire       clk,
    input  wire       rst,
    input  wire       rx_serial,
    output reg  [7:0] rx_data,
    output reg        rx_done
);
    localparam IDLE  = 2'b00,
               START = 2'b01,
               DATA  = 2'b10,
               STOP  = 2'b11;

    reg [1:0] state;
    reg [2:0] bit_idx;
    reg [7:0] rx_shreg;
    reg rx_sync0, rx_sync1;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state     <= IDLE;
            rx_done   <= 1'b0;
            rx_data   <= 8'd0;
            rx_shreg  <= 8'd0;
            bit_idx   <= 3'd0;
            rx_sync0  <= 1'b1;
            rx_sync1  <= 1'b1;
        end else begin
            rx_sync0 <= rx_serial;
            rx_sync1 <= rx_sync0;
            rx_done  <= 1'b0;

